class IndependentSpyAaplStrategies(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.add_equity(ticker, Resolution.DAILY).symbol

        self.spy_bars = RollingWindow[TradeBar](101)
        self.aapl_bars = RollingWindow[TradeBar](2)
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.spy_lot = 0
        self.aapl_lot = 0

    def on_data(self, data: Slice):
        # Update market-state data continuously for every ticker that has a bar.
        if data.bars.contains_key(self.symbols["SPY"]):
            self.spy_bars.add(data.bars[self.symbols["SPY"]])

        if data.bars.contains_key(self.symbols["AAPL"]):
            aapl_bar = data.bars[self.symbols["AAPL"]]
            self.aapl_bars.add(aapl_bar)
            self.aapl_rsi.update(aapl_bar.end_time, aapl_bar.close)

        # Skip all rule evaluation unless every subscribed ticker has today's bar.
        if not all(data.bars.contains_key(symbol) for symbol in self.symbols.values()):
            return

        # Do not trade until every required input is fully formed.
        if not self.spy_bars.is_ready or not self.aapl_bars.is_ready or not self.aapl_rsi.is_ready:
            return

        spy_today = self.spy_bars[0].close
        spy_yesterday = self.spy_bars[1].close
        spy_sma_today = sum(self.spy_bars[i].close for i in range(100)) / 100
        spy_sma_yesterday = sum(self.spy_bars[i].close for i in range(1, 101)) / 100

        spy_crosses_above = spy_yesterday <= spy_sma_yesterday and spy_today > spy_sma_today
        spy_crosses_below = spy_yesterday >= spy_sma_yesterday and spy_today < spy_sma_today

        aapl_today = self.aapl_bars[0].close
        aapl_yesterday = self.aapl_bars[1].close
        aapl_red_streak = 0
        for i in range(self.aapl_bars.count - 1):
            if self.aapl_bars[i].close < self.aapl_bars[i + 1].close:
                aapl_red_streak += 1
            else:
                break

        # Sells before buys.
        if self.spy_lot > 0 and spy_crosses_below:
            self.market_order(self.symbols["SPY"], -self.spy_lot)
            self.spy_lot = 0

        if self.aapl_lot > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.symbols["AAPL"], -self.aapl_lot)
            self.aapl_lot = 0

        if self.spy_lot == 0 and spy_crosses_above:
            shares = int((self.portfolio.total_portfolio_value * 0.40) // spy_today)
            if shares > 0:
                self.market_order(self.symbols["SPY"], shares)
                self.spy_lot = shares

        if self.aapl_lot == 0 and aapl_red_streak >= 3:
            if self.portfolio.cash >= 20_000:
                shares = int(20_000 // aapl_today)
                if shares > 0:
                    self.market_order(self.symbols["AAPL"], shares)
                    self.aapl_lot = shares

